/**
 * Demonstrates command injection via Runtime.exec(String) on line 67 of
 * VulnerableTaskHolder.java.
 *
 * Runtime.exec(String) splits on whitespace and passes tokens as argv to the
 * first-token program. Shell metacharacters (;, &&, |) do NOT chain commands,
 * but an attacker CAN inject extra arguments to the program being run.
 *
 * This test shows that a crafted taskAction like "ping -c 3 127.0.0.1" causes
 * the process to run with the injected -c 3 argument, taking ~3 seconds instead
 * of the expected ~1 second for a single ping. This proves the user-controlled
 * string is passed unsanitized to the process launcher.
 */
public class VulnerableTaskHolderCommandInjectionTest {

  @Test
  public void commandInjectionAllowsArgumentInjection() throws Exception {
    // Craft a taskAction that injects an extra argument (-c 3) to ping,
    // causing it to send 3 packets instead of 1. This takes ~3 seconds.
    // Length is 19 chars, under the 22-char limit.
    String maliciousTaskAction = "ping -c 3 127.0.0.1";
    VulnerableTaskHolder holder = new VulnerableTaskHolder("test", maliciousTaskAction);

    // Serialize
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    try (ObjectOutputStream oos = new ObjectOutputStream(baos)) {
      oos.writeObject(holder);
    }

    // Deserialize — this triggers readObject() which calls Runtime.exec(taskAction)
    long start = System.currentTimeMillis();
    try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(baos.toByteArray()))) {
      ois.readObject();
    }
